    for key, t in data["tables"].items():
        total = t["segments"]["total"]
        options = list(total["responses"])
        rows = [
            [
                esc(n),
                *["–" if v is None else str(v) + "%" for v in r["responses"].values()],
                str(r.get("base_ponderada", "não publicada")),
            ]
            for n, r in t["segments"].items()
